<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {route} from '../router';import {runs} from '../stores/runs';import {reviews} from '../stores/reviews';import {canWrite} from '../stores/auth';import {searchReasons} from '../constants/enums';import {useTask} from '../hooks/useTask';import {fixed} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import MatchMetrics from '../components/MatchMetrics.vue';import MatchLedger from '../components/MatchLedger.vue';import UnmatchedTable from '../components/UnmatchedTable.vue';const selected=ref(route.value.query.get('run')||'demo-run'),stage=ref('all'),action=ref('逐条核对一对一与合并组；未配项及受限搜索保留复核。批准仅留档，不连接银行或自动核销；两阶段不保证联合全局最优。'),notice=ref('');watch(()=>route.value.query.get('run'),v=>{selected.value=v||'demo-run'});const {error,busy,act}=useTask();let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();timer=setInterval(runs.load,2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result),matches=computed(()=>result.value?[...result.value.phase_one.matches,...result.value.phase_two.groups].filter(r=>stage.value==='all'||r.stage===stage.value):[]);function submit(){act(async()=>{await reviews.create({run_id:selected.value,action:action.value});notice.value='匹配复核已提交，等待管理员批准。'})}</script><template><PageHeading index="04 / 运行底稿" title="找到候选，也留下拒配和未配的证据。" note="先全局一对一，再对未使用项做受限组合。每个委托和凭证在本次结果中最多消耗一次，金额差额保持整数分。"/><div class="result-toolbar"><label>运行记录<select v-model="selected"><option v-for="r in runs.items.value" :key="r.id" :value="r.id">{{r.id==='demo-run'?'十一月基线':r.id.slice(0,8)}} · {{r.status}}</option></select></label><StatusPill v-if="run" :status="run.status"/></div><Notice :message="error||runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="后台worker正在计算拒配全局匹配与受限子集和，结果每两秒刷新。"/><template v-if="run?.status==='completed'&&result"><MatchMetrics :result="result"/><div class="result-columns"><section><div class="stage-controls"><h2>匹配与合并候选</h2><label>查看阶段<select v-model="stage"><option value="all">全部候选</option><option value="one_to_one">一对一</option><option value="merged">合并付款</option></select></label></div><MatchLedger :rows="matches"/><h2 class="section-space">仍未配分录</h2><UnmatchedTable :rows="result.unmatched.receipts.concat(result.unmatched.milestones)"/></section><aside class="margin-note"><p class="eyebrow">TRACE & LIMITS</p><h2>拒配与搜索口径</h2><p>第一阶段目标总分{{fixed(result.phase_one.objective_with_rejections)}}（含双侧拒配），兼容边{{result.phase_one.compatible_edges}}条。</p><p>容差{{result.policy.amount_tolerance}}分，日期≤{{result.policy.max_days}}天，引用{{result.policy.require_reference?'必须相同':'软罚分'}}。</p><p>{{result.assumption}}</p><h3>合并搜索未命中/限额</h3><ul class="search-notes"><li v-for="s in result.phase_two.searches.filter((x:any)=>!x.found||x.truncated)" :key="s.receipt_id"><strong>{{s.receipt_id}}</strong> {{searchReasons[s.reason]||'候选截断'}}<small>候选{{s.candidates}} · 截断{{s.truncated}}</small></li></ul><p class="hash-note">输入SHA256<br>{{result.input_sha256}}</p></aside></div><form v-if="canWrite()" class="review-form" @submit.prevent="submit"><label>人工复核说明<textarea v-model="action" rows="4" required minlength="8"></textarea></label><button :disabled="busy">提交匹配复核</button><p class="success" v-if="notice">{{notice}}</p></form></template></template>
